#include <iostream>
using namespace std;

int main() {
    int age = 20;
    int score = 85;

    // if-else if-else
    if (age < 13) {
        cout << "Child" << endl;
    } else if (age < 20) {
        cout << "Teenager" << endl;
    } else {
        cout << "Adult" << endl;
    }

    // Ternary operator
    string result = (score >= 60) ? "Pass" : "Fail";
    cout << "Result: " << result << endl;

    // Logical operators
    bool hasID = true;
    if (age >= 18 && hasID) {
        cout << "Access granted" << endl;
    }

    // Switch statement
    int day = 3;
    switch (day) {
        case 1: cout << "Monday"; break;
        case 2: cout << "Tuesday"; break;
        case 3: cout << "Wednesday"; break;
        default: cout << "Other day";
    }

    return 0;
}

#include <iostream>
using namespace std;

int main() {
    // While loop
    cout << "While loop:" << endl;
    int i = 0;
    while (i < 3) {
        cout << i << " ";
        i++;
    }

    // Do-while loop
    cout << "\n\nDo-while loop:" << endl;
    int j = 0;
    do {
        cout << j << " ";
        j++;
    } while (j < 3);

    // For loop
    cout << "\n\nFor loop:" << endl;
    for (int k = 0; k < 3; k++) {
        cout << k << " ";
    }

    // Break and continue
    cout << "\n\nBreak and continue:" << endl;
    for (int m = 0; m < 5; m++) {
        if (m == 2) continue; // Skip 2
        if (m == 4) break;    // Stop at 4
        cout << m << " ";
    }

    return 0;
}

#include <iostream>
using namespace std;

int main() {
    // One-dimensional array
    int numbers[5] = {10, 20, 30, 40, 50};

    cout << "Array elements:" << endl;
    for (int i = 0; i < 5; i++) {
        cout << "numbers[" << i << "] = " << numbers[i] << endl;
    }

    // Using sizeof to get array length
    int length = sizeof(numbers) / sizeof(numbers[0]);
    cout << "\nArray length: " << length << endl;

    // Range-based for loop (foreach)
    cout << "\nUsing foreach:" << endl;
    for (int num : numbers) {
        cout << num << " ";
    }

    // Two-dimensional array
    cout << "\n\n2D Array:" << endl;
    int matrix[2][3] = {{1, 2, 3}, {4, 5, 6}};
    for (int i = 0; i < 2; i++) {
        for (int j = 0; j < 3; j++) {
            cout << matrix[i][j] << " ";
        }
        cout << endl;
    }

    return 0;
}

#include <iostream>
#include <string>
using namespace std;

// Structure definition
struct Student {
    string name;
    int age;
    char grade;
    double gpa;
};

// Enum definition
enum Weekday {
    MONDAY,
    TUESDAY,
    WEDNESDAY,
    THURSDAY,
    FRIDAY,
    SATURDAY,
    SUNDAY
};

int main() {
    // Using structure
    Student student1;
    student1.name = "Alice";
    student1.age = 20;
    student1.grade = 'A';
    student1.gpa = 3.8;

    cout << "Student: " << student1.name << endl;
    cout << "Age: " << student1.age << endl;
    cout << "Grade: " << student1.grade << endl;
    cout << "GPA: " << student1.gpa << endl;

    // Using enum
    Weekday today = WEDNESDAY;
    cout << "\nToday is day number: " << today << endl;

    // Enum in switch statement
    switch(today) {
        case MONDAY:
            cout << "Start of the week!" << endl;
            break;
        case WEDNESDAY:
            cout << "Middle of the week!" << endl;
            break;
        case FRIDAY:
            cout << "Weekend is near!" << endl;
            break;
        default:
            cout << "Regular day" << endl;
    }

    return 0;
}

#include <iostream>
using namespace std;

int main() {
    // Basic pointers
    int number = 42;
    int* ptr = &number;

    cout << "Value of number: " << number << endl;
    cout << "Address of number: " << &number << endl;
    cout << "Value of ptr: " << ptr << endl;
    cout << "Value at ptr: " << *ptr << endl;

    // Modifying through pointer
    *ptr = 100;
    cout << "\nAfter modification: " << number << endl;

    // Dynamic memory allocation
    int* dynamicPtr = new int;
    *dynamicPtr = 200;
    cout << "\nDynamic value: " << *dynamicPtr << endl;
    delete dynamicPtr; // Clean up

    // Dynamic array
    int size = 3;
    int* arr = new int[size];
    for (int i = 0; i < size; i++) {
        arr[i] = (i + 1) * 10;
    }

    cout << "\nDynamic array: ";
    for (int i = 0; i < size; i++) {
        cout << arr[i] << " ";
    }

    delete[] arr; // Clean up array

    // References
    int original = 50;
    int& ref = original;
    ref = 75;
    cout << "\n\nAfter reference modification: " << original << endl;

    return 0;
}

