#include <iostream>
#include <string>
using namespace std;

// Pass by reference example
void swapNumbers(int &a, int &b) {
    int temp = a;
    a = b;
    b = temp;
}

// Function overloading examples
int multiply(int a, int b) {
    return a * b;
}

double multiply(double a, double b) {
    return a * b;
}

int multiply(int a, int b, int c) {
    return a * b * c;
}

// Recursion example
int factorial(int n) {
    if (n <= 1) return 1;
    return n * factorial(n - 1);
}

// Global variable
int globalCounter = 0;

void incrementCounter() {
    globalCounter++;
    int localVar = 5; // Local variable
    cout << "Local: " << localVar << ", Global: " << globalCounter << endl;
}

int main() {
    // Pass by reference
    int x = 5, y = 10;
    cout << "Before swap: x=" << x << ", y=" << y << endl;
    swapNumbers(x, y);
    cout << "After swap: x=" << x << ", y=" << y << endl;

    // Function overloading
    cout << "multiply(3, 4): " << multiply(3, 4) << endl;
    cout << "multiply(2.5, 1.5): " << multiply(2.5, 1.5) << endl;
    cout << "multiply(2, 3, 4): " << multiply(2, 3, 4) << endl;

    // Recursion
    cout << "factorial(5): " << factorial(5) << endl;

    // Variable scope
    incrementCounter();
    incrementCounter();

    // Lambda function
    auto greet = [](string name) {
        cout << "Hello, " << name << "!" << endl;
    };

    greet("World");

    return 0;
}

#include <iostream>
using namespace std;

int main() {
    // Creating an enum
    enum Level {
        LOW,      // Value: 0
        MEDIUM,   // Value: 1  
        HIGH      // Value: 2
    };

    cout << "--- Basic Enum Example ---" << endl;

    // Creating enum variable
    Level myLevel = MEDIUM;

    // Using enum
    cout << "Current level: " << myLevel << endl;  // Outputs: 1

    // Enum with custom values
    enum Priority {
        LOW_PRIORITY = 10,
        MEDIUM_PRIORITY = 50,
        HIGH_PRIORITY = 100
    };

    cout << "\n--- Enum with Custom Values ---" << endl;
    Priority taskPriority = HIGH_PRIORITY;
    cout << "Task priority value: " << taskPriority << endl;

    // Auto-incrementing values
    enum Status {
        PENDING = 1,  // 1
        PROCESSING,   // 2 (auto-incremented)
        COMPLETED     // 3 (auto-incremented)
    };

    cout << "\n--- Auto-incrementing Enum ---" << endl;
    Status currentStatus = PROCESSING;
    cout << "Status value: " << currentStatus << endl;

    // Enum in switch statement
    cout << "\n--- Enum in Switch Statement ---" << endl;
    Level userLevel = HIGH;

    switch(userLevel) {
        case LOW:
            cout << "Easy mode selected" << endl;
            break;
        case MEDIUM:
            cout << "Normal mode selected" << endl;
            break;
        case HIGH:
            cout << "Hard mode selected" << endl;
            break;
    }

    // Practical example: Days of week
    enum Day {
        SUNDAY,    // 0
        MONDAY,    // 1
        TUESDAY,   // 2
        WEDNESDAY, // 3
        THURSDAY,  // 4
        FRIDAY,    // 5
        SATURDAY   // 6
    };

    cout << "\n--- Days of Week Example ---" << endl;
    Day today = FRIDAY;

    if (today == FRIDAY) {
        cout << "It's Friday! Weekend is coming!" << endl;
    }

    // Comparing enum values
    cout << "\n--- Enum Comparisons ---" << endl;
    Level level1 = LOW;
    Level level2 = HIGH;

    if (level1 < level2) {
        cout << "LOW is less than HIGH" << endl;
    }

    return 0;
}

#include <iostream>
#include <string>
using namespace std;

int main() {
    cout << "--- Creating References ---" << endl;

    // Original variable
    string food = "Pizza";

    // Creating a reference (alias)
    string &meal = food;

    cout << "food: " << food << endl;
    cout << "meal: " << meal << endl;
    cout << "Address of food: " << &food << endl;
    cout << "Address of meal: " << &meal << endl;

    cout << "\n--- Modifying Through References ---" << endl;

    // Changing through reference
    meal = "Burger";

    cout << "After changing meal:\n";
    cout << "food: " << food << endl;  // Also changed!
    cout << "meal: " << meal << endl;

    // Changing through original
    food = "Pasta";

    cout << "\nAfter changing food:\n";
    cout << "food: " << food << endl;
    cout << "meal: " << meal << endl;  // Also changed!

    cout << "\n--- Reference with Different Data Types ---" << endl;

    // Integer reference
    int number = 100;
    int &numRef = number;

    cout << "number: " << number << endl;
    numRef = 200;
    cout << "After numRef = 200:\n";
    cout << "number: " << number << endl;

    // Array reference (C++11 feature)
    int arr[3] = {1, 2, 3};
    int (&arrRef)[3] = arr;

    cout << "\nArray reference:\n";
    arrRef[0] = 10;
    cout << "arr[0]: " << arr[0] << endl;

    cout << "\n--- Practical Example: Function Parameters ---" << endl;

    // Function using reference parameter
    auto swapNumbers = [](int &a, int &b) {
        int temp = a;
        a = b;
        b = temp;
    };

    int x = 5, y = 10;
    cout << "Before swap: x=" << x << ", y=" << y << endl;
    swapNumbers(x, y);
    cout << "After swap: x=" << x << ", y=" << y << endl;

    cout << "\n--- Const References ---" << endl;

    // Const reference (read-only)
    const string &readOnlyRef = food;

    cout << "Original food: " << readOnlyRef << endl;
    // readOnlyRef = "New Food";  // ERROR: Cannot modify const reference

    // But original can still change
    food = "Salad";
    cout << "After food change: " << readOnlyRef << endl;

    cout << "\n--- Reference vs Pointer ---" << endl;

    string city = "Karachi";
    string &cityRef = city;      // Reference
    string *cityPtr = &city;     // Pointer

    cout << "city: " << city << endl;
    cout << "cityRef: " << cityRef << endl;
    cout << "*cityPtr: " << *cityPtr << endl;

    // Key difference: reference cannot be null
    // string &badRef;  // ERROR: Must initialize
    string *badPtr = nullptr;  // OK: Pointer can be null

    return 0;
}

#include <iostream>
using namespace std;

int main() {
    cout << "--- Basic Boolean Variables ---" << endl;

    // Declaring boolean variables
    bool isCodingFun = true;
    bool isFishTasty = false;

    cout << "Is coding fun? " << isCodingFun << endl;     // Outputs: 1
    cout << "Is fish tasty? " << isFishTasty << endl;     // Outputs: 0

    cout << "\n--- Using boolalpha ---" << endl;

    // Display as true/false instead of 1/0
    cout << boolalpha;
    cout << "Is coding fun? " << isCodingFun << endl;     // Outputs: true
    cout << "Is fish tasty? " << isFishTasty << endl;     // Outputs: false

    cout << "\n--- Switching Back with noboolalpha ---" << endl;
    cout << noboolalpha;
    cout << "Back to numbers: " << isCodingFun << endl;   // Outputs: 1

    cout << "\n--- Boolean from Comparisons ---" << endl;

    int x = 10, y = 5;
    bool result;

    result = (x > y);     // true
    cout << "x > y: " << boolalpha << result << endl;

    result = (x == y);    // false
    cout << "x == y: " << result << endl;

    result = (x != y);    // true
    cout << "x != y: " << result << endl;

    cout << "\n--- Logical Operators ---" << endl;

    bool a = true;
    bool b = false;

    cout << "a = " << a << ", b = " << b << endl;
    cout << "a && b (AND): " << (a && b) << endl;      // false
    cout << "a || b (OR): " << (a || b) << endl;       // true
    cout << "!a (NOT): " << (!a) << endl;              // false

    cout << "\n--- Practical Examples ---" << endl;

    // Age verification
    int age = 18;
    bool isAdult = (age >= 18);

    cout << "Age: " << age << endl;
    cout << "Is adult? " << isAdult << endl;

    if (isAdult) {
        cout << "Access granted!" << endl;
    }

    // Login system
    string username = "admin";
    string password = "12345";

    bool isValidUser = (username == "admin");
    bool isValidPass = (password == "12345");
    bool canLogin = isValidUser && isValidPass;

    cout << "\nLogin System:" << endl;
    cout << "Valid username? " << isValidUser << endl;
    cout << "Valid password? " << isValidPass << endl;
    cout << "Can login? " << canLogin << endl;

    // Toggle switch
    bool lightOn = false;
    cout << "\nLight switch example:" << endl;
    cout << "Light is on? " << lightOn << endl;

    // Toggle the light
    lightOn = !lightOn;  // NOT operator toggles
    cout << "After toggle: " << lightOn << endl;

    // Toggle again
    lightOn = !lightOn;
    cout << "Toggle again: " << lightOn << endl;

    cout << "\n--- Boolean in Arrays ---" << endl;

    bool attendance[5] = {true, false, true, true, false};

    cout << "Attendance record:" << endl;
    for (int i = 0; i < 5; i++) {
        cout << "Student " << (i+1) << ": " << (attendance[i] ? "Present" : "Absent") << endl;
    }

    cout << "\n--- Boolean Size ---" << endl;
    cout << "Size of bool: " << sizeof(bool) << " byte(s)" << endl;

    return 0;
}

#include <iostream>
using namespace std;

int main() {
    cout << "--- break Statement ---" << endl;

    // break in for loop
    cout << "Counting 1-10 (stops at 5):" << endl;
    for (int i = 1; i <= 10; i++) {
        if (i == 6) {
            break;  // Exit loop when i reaches 6
        }
        cout << i << " ";
    }
    cout << endl;

    // break in while loop
    cout << "\nWhile loop with break:" << endl;
    int count = 1;
    while (true) {  // Infinite loop
        cout << count << " ";
        if (count == 5) {
            break;  // Exit infinite loop
        }
        count++;
    }
    cout << endl;

    cout << "\n--- continue Statement ---" << endl;

    // continue in for loop (skip even numbers)
    cout << "Odd numbers 1-10:" << endl;
    for (int i = 1; i <= 10; i++) {
        if (i % 2 == 0) {  // If even
            continue;      // Skip to next iteration
        }
        cout << i << " ";
    }
    cout << endl;

    // continue in while loop
    cout << "\nWhile loop with continue (skip 5):" << endl;
    int num = 0;
    while (num < 10) {
        num++;
        if (num == 5) {
            continue;  // Skip number 5
        }
        cout << num << " ";
    }
    cout << endl;

    cout << "\n--- Practical Examples ---" << endl;

    // Example 1: Search array
    int numbers[] = {10, 20, 30, 40, 50, 60, 70};
    int searchValue = 40;
    bool found = false;

    cout << "Searching for " << searchValue << ":" << endl;
    for (int i = 0; i < 7; i++) {
        if (numbers[i] == searchValue) {
            cout << "Found at position " << i << endl;
            found = true;
            break;  // Stop searching once found
        }
    }
    if (!found) {
        cout << "Not found" << endl;
    }

    // Example 2: Skip invalid data
    cout << "\nProcessing data (skip negative):" << endl;
    int data[] = {5, -3, 10, -1, 15, 20};

    for (int i = 0; i < 6; i++) {
        if (data[i] < 0) {
            cout << "Skipping negative: " << data[i] << endl;
            continue;  // Skip negative numbers
        }
        cout << "Processing: " << data[i] << endl;
    }

    // Example 3: Password attempts
    cout << "\n--- Login System (3 attempts) ---" << endl;
    string correctPassword = "secret123";
    int attempts = 3;

    for (int attempt = 1; attempt <= attempts; attempt++) {
        string input;
        cout << "Attempt " << attempt << ": Enter password: ";
        // In real program, you would get actual input

        // Simulating wrong attempts
        if (attempt < 3) {
            cout << "[Wrong password]" << endl;
            continue;  // Try again
        } else {
            cout << "[Correct password]" << endl;
            cout << "Login successful!" << endl;
            break;  // Exit loop on success
        }
    }

    cout << "\n--- break in Nested Loops ---" << endl;
    // break only exits the innermost loop
    cout << "Nested loops (break exits inner loop only):" << endl;
    for (int i = 1; i <= 3; i++) {
        for (int j = 1; j <= 3; j++) {
            if (j == 2) {
                break;  // Only breaks inner j-loop
            }
            cout << "i=" << i << ", j=" << j << endl;
        }
    }

    return 0;
}
